khóa"}, {"quote_id": "P2.Q9", "evidence_id": "P2", "text": "Kim 25 hoặc 27 gauge: dài 3 cm đối với các trường hợp phong bế dây thần kinh"}], "public_sources": [{"evidence_id": "P1", "title": "Cách thực hiện phong bế dây thần kinh cằm", "heading_path": ["Những cân nhắc bổ sung trong phong bế dây thần kinh cằm"]}, {"evidence_id": "P2", "title": "Cách thực hiện phong bế dây thần kinh cằm", "heading_path": ["Dụng cụ trong phong bế dây thần kinh cằm"]}]}
